  "implementation": "def solve(case):
    # Validate input
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('Missing nodes or required_symbols')
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build node map and children
    node_map = {}
    children_map = {}
    root_id = None
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        children_map.setdefault(nid, [])
        parent = node.get('parent')
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            children_map.setdefault(parent, []).append(nid)
    if root_id is None:
        raise ValueError('No root node')
    root = node_map[root_id]
    if root['symbol'] not in required_symbols:
        raise ValueError('Root symbol not in required_symbols')

    # Prepare candidate list: removable, not root, symbol not required
    candidates = []
    for node in nodes:
        nid = node['id']
        if node.get('removable') and nid != root_id and node['symbol'] not in required_symbols:
            depth = node.get('depth', 0)
            candidates.append((-depth, nid))  # sort by -depth for descending
    candidates.sort(key=lambda x: (x[0], x[1]))  # depth descending, then id ascending

    removed_set = set()
    removed_order = []

    # Helper to get all retained descendants of a node (including itself)
    def get_descendants(nid):
        stack = [nid]
        descendants = set()
        while stack:
            cur = stack.pop()
            if cur in removed_set or cur in descendants:
                continue
            descendants.add(cur)
            for child in children_map.get(cur, []):
                if child not in removed_set:
                    stack.append(child)
        return descendants

    # Process candidates
    for neg_depth, nid in candidates:
        if nid in removed_set:
            continue
        # Get descendants (subtree) that are still retained
        subtree = get_descendants(nid)
        # Check if any child of this node is retained after removal? 
        # Since we remove entire subtree, no child will be retained. But we must also ensure no child is outside subtree (impossible).
        # Actually we need to check condition: node with retained children is not removed.
        # Because subtree includes all children, all children will be removed. So automatically satisfied.
        # Compute new removed set
        new_removed = removed_set | subtree
        # Compute symbols of retained nodes
        retained_symbols = set()
        for node in nodes:
            if node['id'] not in new_removed:
                retained_symbols.add(node['symbol'])
        if required_symbols.issubset(retained_symbols):
            # Accept removal
            removed_set = new_removed
            removed_order.append(nid)

    # Retained node ids sorted
    retained_ids = sorted([node['id'] for node in nodes if node['id'] not in removed_set])
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_ids}"
}
